// Protocol — the highest-value producer in the repo, and it needs zero new code.
//
// The generator is already byte-reproducible (the existing `protocol-codegen`
// CI job proves determinism). Vibes turns the actual C/TS/Rust diff into the
// reviewable artifact: change one line of MaDProtocol.yaml and the report shows
// exactly which generated bytes moved in all three languages.
export default {
  component: 'protocol',

  producers: ['c', 'ts', 'rs'].map((target) => ({
    name: `codegen-${target}`,
    description: `Generate the ${target.toUpperCase()} codec from MaDProtocol.yaml.`,
    // Exactly the CLI from CLAUDE.md and ci.yml's protocol-codegen job, with
    // $VIBES_OUT_DIR substituted for the hardcoded destination.
    cmd: `python3 ProtoEmb/core/generate.py --schema MaDProtocol.yaml`
       + ` --target ${target} --output "$VIBES_OUT_DIR" --templates ProtoEmb/core/templates`,
    out: `snapshots/codegen/${target}`,
    ciJob: 'protocol-codegen',
    tier: 'pr',
  })),

  witnesses: [
    'MaDProtocol.yaml',
    'scripts/check_schema_domain_lockstep.py',
    'rust/src/lib.rs',
  ],
  // NOT witnessable: ProtoEmb/core/templates/** and ProtoEmb/core/generate.py
  // live inside the Protocol/ProtoEmb submodule, and `git ls-files Protocol/ProtoEmb`
  // returns only the gitlink. That gap is declared as `submodules` in the registry,
  // so a pin bump still forces this component to run.
};
